    public function record(string $stage, string $result, ?string $component = null, ?Throwable $error = null): void
    {
        if ($this->enabled) {
            $this->steps[] = ['stage' => $stage, 'result' => $result, 'component' => $component, 'exception' => $error === null ? null : $error::class];
        }
    }

